
(function(){
 const shareSvg='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="18" cy="5" r="2.5"></circle><circle cx="6" cy="12" r="2.5"></circle><circle cx="18" cy="19" r="2.5"></circle><path d="M8.2 10.8 15.8 6.3M8.2 13.2l7.6 4.5"></path></svg>';
 function money(n){return typeof fmt==='function'?fmt(Number(n||0)):'$'+Number(n||0).toLocaleString('es-CO')}
 function wrap(ctx,text,maxWidth,maxLines=99){const words=String(text||'').split(/\s+/).filter(Boolean),lines=[];let line='';for(const word of words){const t=line?line+' '+word:word;if(ctx.measureText(t).width>maxWidth&&line){lines.push(line);line=word;if(lines.length>=maxLines-1)break}else line=t}if(line&&lines.length<maxLines)lines.push(line);return lines}
 async function shareCanvas(canvas,name,title){const blob=await new Promise(r=>canvas.toBlob(r,'image/png',.94));if(!blob)throw new Error('No se pudo crear la imagen');const file=new File([blob],name,{type:'image/png'});await window.liftShareGeneratedImage(blob,file,title)}
 function drawHeader(ctx,W,title){ctx.fillStyle='#0b0b0b';ctx.fillRect(0,0,W,128);ctx.fillStyle='#fff';ctx.font='700 40px Poppins,Arial';ctx.fillText('LIFT NUTRIENTES',55,55);ctx.font='500 25px Poppins,Arial';ctx.fillText(title,55,96)}
 async function drawProduct(ctx,p,q,y,W){const rowH=205;ctx.strokeStyle='#e7e7e7';ctx.beginPath();ctx.moveTo(55,y+rowH-10);ctx.lineTo(W-55,y+rowH-10);ctx.stroke();try{const img=await liftLoadShareImage(p.image);if(img){const r=Math.min(140/img.width,140/img.height);ctx.drawImage(img,60+(140-img.width*r)/2,y+10+(140-img.height*r)/2,img.width*r,img.height*r)}}catch(e){}ctx.fillStyle='#777';ctx.font='500 19px Poppins,Arial';ctx.fillText(String(p.brand||'').toUpperCase(),225,y+32);ctx.fillStyle='#111';ctx.font='600 25px Poppins,Arial';wrap(ctx,p.name,720,2).forEach((ln,i)=>ctx.fillText(ln,225,y+70+i*33));if(p._cartFlavor){ctx.fillStyle='#666';ctx.font='500 18px Poppins,Arial';ctx.fillText('Sabor: '+p._cartFlavor,225,y+137)}const promoDate=typeof offerUntilText==='function'?offerUntilText(p):'';if(promoDate){ctx.fillStyle='#666';ctx.font='500 16px Poppins,Arial';ctx.fillText('Oferta hasta '+promoDate,225,y+158)}const unit=(typeof checkoutUnitPrice==='function'?checkoutUnitPrice(p):priceOf(p));const promo=(typeof savingOf==='function'&&savingOf(p)>0&&unit===priceOf(p));if(promo){const old=money(compareAtOf(p)*q);ctx.fillStyle='#8a8a8a';ctx.font='500 18px Poppins,Arial';ctx.fillText(old,225,y+178);const ow=ctx.measureText(old).width;ctx.strokeStyle='#8a8a8a';ctx.beginPath();ctx.moveTo(225,y+171);ctx.lineTo(225+ow,y+171);ctx.stroke();ctx.fillStyle='#168451';ctx.font='700 27px Poppins,Arial';ctx.fillText(money(unit*q),225,y+202)}else{ctx.fillStyle='#111';ctx.font='700 27px Poppins,Arial';ctx.fillText(money(unit*q),225,y+190)};ctx.fillStyle='#666';ctx.font='500 18px Poppins,Arial';ctx.fillText('Cantidad: '+q,W-230,y+172);return rowH}
 // Reemplaza la imagen del carrito de Fase 4 para que siempre muestre el total.
 window.shareLiftCartImage=async function(){try{const rows=typeof items==='function'?items():[];if(!rows.length){liftShareToast('No hay productos en el carrito');return}liftShareToast('Creando imagen…');const W=1080,rowH=205,H=128+45+rows.length*rowH+190,c=document.createElement('canvas');c.width=W;c.height=H;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,W,H);drawHeader(ctx,W,'Tu carrito');let y=165,total=0;for(const row of rows){const p=row.p,q=row.q||1;total+=priceOf(p)*q;y+=await drawProduct(ctx,p,q,y,W)}ctx.fillStyle='#111';ctx.font='600 24px Poppins,Arial';ctx.fillText('TOTAL',55,H-105);ctx.font='700 38px Poppins,Arial';const txt=money(total);ctx.fillText(txt,W-55-ctx.measureText(txt).width,H-102);ctx.fillStyle='#777';ctx.font='500 18px Poppins,Arial';ctx.fillText('Total de productos. El envío se calcula al finalizar la compra.',55,H-55);await shareCanvas(c,'lift-carrito.png','Carrito Lift Nutrientes')}catch(e){console.error(e);liftShareToast('No se pudo generar la imagen')}};
 function injectCheckoutShare(){const send=document.querySelector('#checkoutModal .checkoutSend');if(!send||document.getElementById('liftCheckoutShareBtn'))return;const b=document.createElement('button');b.id='liftCheckoutShareBtn';b.type='button';b.className='checkoutShareOrder';b.innerHTML=shareSvg+'<span>Compartir pedido con datos</span>';b.onclick=()=>shareLiftCheckoutImage();send.insertAdjacentElement('afterend',b)}
 window.shareLiftCheckoutImage=async function(){try{const name=document.getElementById('coName').value.trim(),phone=document.getElementById('coPhone').value.trim(),address=document.getElementById('coAddress').value.trim(),notes=document.getElementById('coNotes').value.trim();if(!name||!phone||!address||!selectedCity){alert('Completa nombre, celular, dirección y selecciona una ciudad antes de compartir el pedido.');return}const rows=checkoutItemsList();if(!rows.length)return;liftShareToast('Creando pedido…');const sub=checkoutPublicSubtotal(rows),effectiveSub=checkoutEffectiveSubtotal(rows),autoShip=adminTrainerMode()?11000:shippingFor(selectedCity.name,checkoutQty()),ship=(typeof window.liftAdminShippingValue==='function'?window.liftAdminShippingValue(autoShip):autoShip),discount=checkoutCouponDiscount(rows),total=Math.max(0,effectiveSub-((adminTrainerMode()||trainerCouponActive())?0:discount))+(ship||0);const info=[];info.push(['Cliente',name],['Celular',phone],['Dirección',address],['Ciudad',selectedCity.name+(selectedCity.department?' · '+selectedCity.department:'')]);if(notes)info.push(['Notas',notes]);if(appliedCoupon)info.push(['Cupón',appliedCoupon.code]);const W=1080,rowH=205;let infoLines=0;const tmp=document.createElement('canvas').getContext('2d');tmp.font='500 21px Poppins,Arial';for(const [,v] of info)infoLines+=Math.max(1,wrap(tmp,v,750,3).length);const infoH=125+infoLines*42;const totalsH=245;const H=128+infoH+45+rows.length*rowH+totalsH;const c=document.createElement('canvas');c.width=W;c.height=H;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,W,H);drawHeader(ctx,W,'Pedido');let y=165;
// Datos del cliente mucho más visibles: bloque independiente, título y valores grandes.
ctx.fillStyle='#f4f4f4';ctx.beginPath();ctx.roundRect(45,y-22,W-90,infoH+18,22);ctx.fill();
ctx.fillStyle='#111';ctx.font='700 27px Poppins,Arial';ctx.fillText('DATOS DEL CLIENTE',70,y+18);y+=58;
for(const [k,v] of info){
  ctx.fillStyle='#666';ctx.font='700 18px Poppins,Arial';ctx.fillText(k.toUpperCase(),70,y);
  ctx.fillStyle='#111';ctx.font='700 25px Poppins,Arial';
  const ls=wrap(ctx,v,720,3);ls.forEach((ln,i)=>ctx.fillText(ln,270,y+i*34));
  y+=Math.max(1,ls.length)*34+8;
}
y+=26;ctx.fillStyle='#111';ctx.font='700 24px Poppins,Arial';ctx.fillText('PRODUCTOS DEL PEDIDO',55,y);y+=18;ctx.strokeStyle='#cfcfcf';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(55,y);ctx.lineTo(W-55,y);ctx.stroke();ctx.lineWidth=1;y+=25;for(const row of rows)y+=await drawProduct(ctx,row.p,row.q||1,y,W);y+=20;function totalLine(label,value,strong){ctx.fillStyle=strong?'#111':'#555';ctx.font=(strong?'700 29px':'500 22px')+' Poppins,Arial';ctx.fillText(label,55,y);const t=value;ctx.fillText(t,W-55-ctx.measureText(t).width,y);y+=strong?48:37}totalLine('Subtotal',money((adminTrainerMode()||trainerCouponActive())?effectiveSub:sub),false);if(discount)totalLine(trainerCouponActive()?'Precio entrenador / ahorro':'Descuento','-'+money(discount),false);totalLine('Envío',ship===0?'GRATIS':money(ship),false);y+=8;totalLine('TOTAL',money(total),true);ctx.fillStyle='#777';ctx.font='500 17px Poppins,Arial';const exactVariants=rows.some(r=>r.p?._variantId);ctx.fillText(exactVariants?'Los sabores seleccionados quedan incluidos en este pedido.':'Sabores sujetos a disponibilidad y confirmación por WhatsApp.',55,H-38);await shareCanvas(c,'lift-pedido-'+Date.now()+'.png','Pedido Lift Nutrientes')}catch(e){console.error(e);liftShareToast('No se pudo generar el pedido')}};
 document.addEventListener('DOMContentLoaded',injectCheckoutShare);setTimeout(injectCheckoutShare,100);const oldOpenCheckout=window.openCheckout;if(typeof oldOpenCheckout==='function')window.openCheckout=function(){const r=oldOpenCheckout.apply(this,arguments);setTimeout(injectCheckoutShare,0);return r};
})();
